src='''def find_objects(g):
    seen=set(); objs=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j]; stack=[(i,j)]; cells=[]
                seen.add((i,j))
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==c and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                objs.append({'c':c,'h':max(ys)-min(ys)+1,'w':max(xs)-min(xs)+1,'cells':cells,'top_r':min(ys),'top_c':min(xs)})
    for o in objs:
        assert len(o['cells'])==o['h']*o['w']
    objs.sort(key=lambda o:o['top_c'])
    return objs

def transform(grid):
    objs=find_objects(grid)
    out=[[0]*len(grid[0]) for _ in range(len(grid))]
    r=c=0
    for k,o in enumerate(objs):
        if k>0:
            p=objs[k-1]
            r=p['top_r']+p['h']-1; c=p['top_c']+p['w']-1
        o['top_r'],o['top_c']=r,c
        for dy in range(o['h']):
            for dx in range(o['w']):
                out[r+dy][c+dx]=o['c']
    return out
'''
